test("after cutoff Friday skips weekend and Monday holiday and delivery is two later business days", function () {
  var actual = code.promiseDelivery({ bookedAt: "2026-07-03T15:00", transitDays: 2, holidays: ["2026-07-06"] });
  assert.deepEqual(actual, { shipDate: "2026-07-07", deliveryDate: "2026-07-09" });
});

test("before cutoff on a business day ships that day with an empty holiday list and one transit day", function () {
  var actual = code.promiseDelivery({ bookedAt: "2026-07-01T09:00", transitDays: 1, holidays: [] });
  assert.deepEqual(actual, { shipDate: "2026-07-01", deliveryDate: "2026-07-02" });
});

test("time exactly 14:00 is not before cutoff", function () {
  var actual = code.promiseDelivery({ bookedAt: "2026-07-01T14:00", transitDays: 1, holidays: [] });
  assert.deepEqual(actual, { shipDate: "2026-07-02", deliveryDate: "2026-07-03" });
});

test("one minute before cutoff ships same business day and zero transit days means delivery equals ship", function () {
  var actual = code.promiseDelivery({ bookedAt: "2026-07-01T13:59", transitDays: 0, holidays: [] });
  assert.deepEqual(actual, { shipDate: "2026-07-01", deliveryDate: "2026-07-01" });
});

test("one minute after cutoff ships the next business day", function () {
  var actual = code.promiseDelivery({ bookedAt: "2026-07-01T14:01", transitDays: 1, holidays: [] });
  assert.deepEqual(actual, { shipDate: "2026-07-02", deliveryDate: "2026-07-03" });
});

test("Sunday booking ships the next business day and skips the listed Monday holiday", function () {
  var actual = code.promiseDelivery({ bookedAt: "2026-07-05T09:00", transitDays: 1, holidays: ["2026-01-01", "2026-07-06", "2026-12-25"] });
  assert.deepEqual(actual, { shipDate: "2026-07-07", deliveryDate: "2026-07-08" });
});

test("holiday that blocks the next ship day is skipped and a later holiday is not a delivery day", function () {
  var actual = code.promiseDelivery({ bookedAt: "2026-07-03T15:00", transitDays: 2, holidays: ["2026-07-06", "2026-07-08", "2026-12-25"] });
  assert.deepEqual(actual, { shipDate: "2026-07-07", deliveryDate: "2026-07-10" });
});

test("last day of December after cutoff skips January 1 holiday and ships the following Monday", function () {
  var actual = code.promiseDelivery({ bookedAt: "2026-12-31T15:00", transitDays: 1, holidays: ["2026-07-06", "2026-11-26", "2027-01-01"] });
  assert.deepEqual(actual, { shipDate: "2027-01-04", deliveryDate: "2027-01-05" });
});

test("isBusinessDay is false for holidays first middle and last and for Saturday and Sunday and true for an unlisted weekday", function () {
  var holidays = ["2026-01-01", "2026-07-06", "2026-12-25"];
  assert.equal(code.isBusinessDay("2026-01-01", holidays), false);
  assert.equal(code.isBusinessDay("2026-07-06", holidays), false);
  assert.equal(code.isBusinessDay("2026-12-25", holidays), false);
  assert.equal(code.isBusinessDay("2026-07-07", holidays), true);
  assert.equal(code.isBusinessDay("2026-07-04", []), false);
  assert.equal(code.isBusinessDay("2026-07-05", []), false);
});

test("last day of a month before cutoff with one transit day lands on the first of the next month", function () {
  var actual = code.promiseDelivery({ bookedAt: "2026-04-30T13:59", transitDays: 1, holidays: [] });
  assert.deepEqual(actual, { shipDate: "2026-04-30", deliveryDate: "2026-05-01" });
});

test("leap day is a business day and two transit days land on the following Monday", function () {
  var actual = code.promiseDelivery({ bookedAt: "2024-02-29T13:59", transitDays: 2, holidays: [] });
  assert.deepEqual(actual, { shipDate: "2024-02-29", deliveryDate: "2024-03-04" });
});

test("booking on a single listed Monday holiday before 14:00 still ships the next business day", function () {
  var actual = code.promiseDelivery({ bookedAt: "2026-07-06T09:00", transitDays: 1, holidays: ["2026-07-06"] });
  assert.deepEqual(actual, { shipDate: "2026-07-07", deliveryDate: "2026-07-08" });
});

test("whole number forms 3 and 3.0 are both valid and give the same dates", function () {
  var expected = { shipDate: "2026-07-01", deliveryDate: "2026-07-06" };
  var withThree = code.promiseDelivery({ bookedAt: "2026-07-01T09:00", transitDays: 3, holidays: [] });
  var withThreePointZero = code.promiseDelivery({ bookedAt: "2026-07-01T09:00", transitDays: 3.0, holidays: [] });
  assert.deepEqual(withThree, expected);
  assert.deepEqual(withThreePointZero, expected);
});

test("Saturday morning is not a ship day even though the time is before 14:00", function () {
  var actual = code.promiseDelivery({ bookedAt: "2026-07-04T09:00", transitDays: 1, holidays: [] });
  assert.deepEqual(actual, { shipDate: "2026-07-06", deliveryDate: "2026-07-07" });
});

test("named error invalid transitDays for a negative value and for a non-whole value", function () {
  assert.throws(function () {
    code.promiseDelivery({ bookedAt: "2026-07-01T09:00", transitDays: -1, holidays: [] });
  }, /invalid transitDays/);
  assert.throws(function () {
    code.promiseDelivery({ bookedAt: "2026-07-01T09:00", transitDays: 1.5, holidays: [] });
  }, /invalid transitDays/);
});

test("named error for an input field other than bookedAt transitDays or holidays", function () {
  assert.throws(function () {
    code.promiseDelivery({ bookedAt: "2026-07-01T09:00", transitDays: 1, holidays: [], note: "extra" });
  }, /unknown field: note/);
});
